// 月次ダッシュボード生成。metrics.csv から月間データ集計。
const i = $input.first().json;
return [{ json: {
  month: i.month ?? new Date().toISOString().slice(0, 7),
  include_revenue_graph: i.include_revenue_graph ?? true,
  include_kpi_trend: i.include_kpi_trend ?? true,
  include_scaling_proposal: i.include_scaling_proposal ?? true,
  send_to_slack: i.send_to_slack ?? true,
  send_to_email: i.send_to_email ?? false
} }];

// 月間集計: 売上・ROI・KPI を計算
const o = $input.first().json;
const month = o.month;

// サンプルデータ（実運用では metrics.csv から読み込み）
const daily_revenues = [2000, 3500, 1800, 4200, 2900, 3100, 2500]; // 7日間
const total_revenue = daily_revenues.reduce((a, b) => a + b, 0);
const avg_daily = (total_revenue / daily_revenues.length).toFixed(0);
const peak_day = Math.max(...daily_revenues);

const total_cost = 1200; // API + Browser Automation
const gross_profit = total_revenue - total_cost;
const owner_hours = 16;
const kpi_profit_per_hour = (gross_profit / owner_hours).toFixed(1);

const roi_percentage = ((gross_profit / total_cost) * 100).toFixed(1);

return [{ json: { ...o,
  total_revenue, avg_daily, peak_day,
  total_cost, gross_profit, kpi_profit_per_hour,
  roi_percentage,
  summary: `${month}: 売上 ¥${total_revenue} / ROI ${roi_percentage}% / KPI ¥${kpi_profit_per_hour}/時`
} }];

